// 1. Static Initialization Order Fiasco (SIOF)
// Problem: Order of static object construction across TUs is undefined.

class Resource {
  public: Resource() { /* Assumes Dependency is ready */ }
};
class Dependency { /* ... */ };

// File A (Translation Unit 1)
static Dependency global_dep;

// File B (Translation Unit 2)
// If global_dep is initialized after global_res, crash occurs.
static Resource global_res;


// 2. Solution: Meyers Singleton (Function-local static)
// Ensures initialization only upon first access (Lazy Init).
// Thread-safe since C++11.

class Logger { /* ... */ };

Logger& GetLogger() {
    // Guaranteed initialization upon first call
    static Logger instance;
    return instance;
}

// Usage: GetLogger().log("Message");


// 3. Solution: C++20 `constinit` (Compile-Time Initialization)
// Forces initialization into the safe, constant initialization phase.

struct Data { int v; };

constexpr Data make_data(int v) { return {v}; }

// Guaranteed to be initialized before any dynamic initialization starts.
constinit static Data safe_data = make_data(42);
